(1864020, 257206, 23430, '<td valign="top">Very clever and funny. I like it.</td>', 'Very clever and funny. I like it.', '2005-11-14 02:06:13.000000', NULL, 1),
(1864022, 255739, 47487, '<td valign="top">I''m torn. The photo is eye-poppingly beautiful, but it doesn''t lend itself naturally to the triptych format, IMO. Still. 7.</td>', 'I''m torn. The photo is eye-poppingly beautiful, but it doesn''t lend itself naturally to the triptych format, IMO. Still. 7.', '2005-11-14 02:07:05.000000', NULL, 1),
