(1864274, 257112, 47430, '<td valign="top">wow really good</td>', 'wow really good', '2005-11-14 05:08:37.000000', NULL, 1),
(1864275, 256810, 29658, '<td valign="top">I''m not sure I like the choice of the first two''s color. Maybe all b&amp;w with the girl standing in color would have been better, but not sure.</td>', 'I''m not sure I like the choice of the first two''s color. Maybe all b&w with the girl standing in color would have been better, but not sure.', '2005-11-14 05:09:46.000000', NULL, 1),
(1864276, 257445, 47430, '<td valign="top">congratulation :)</td>', 'congratulation :)', '2005-11-14 05:09:49.000000', NULL, 1),
