(1864921, 255933, 42181, '<td valign="top">Lovely looking shots. Meets / beats challenge, great 9</td>', 'Lovely looking shots. Meets / beats challenge, great 9', '2005-11-14 11:58:08.000000', NULL, 1),
(1864927, 257068, 42181, '<td valign="top">3 good shots, great together. 8</td>', '3 good shots, great together. 8', '2005-11-14 12:00:30.000000', NULL, 1),
