(1875338, 255852, 43565, '<td valign="top">Not sure if this is a true triptych, but I love the overlap ot the elements into the other panels.  I would love to know how you did this.  7 for now, and maybe a bump later.  Bumped to 9</td>', 'Not sure if this is a true triptych, but I love the overlap ot the elements into the other panels.  I would love to know how you did this.  7 for now, and maybe a bump later.  Bumped to 9', '2005-11-16 22:10:18.000000', NULL, 1),
(1875393, 256915, 14736, '<td valign="top">Very nice choice of three photos.  They are not only united in theme, but visually go well together.  Good luck.</td>', 'Very nice choice of three photos.  They are not only united in theme, but visually go well together.  Good luck.', '2005-11-16 22:24:01.000000', NULL, 1),
(1875398, 256909, 14736, '<td valign="top">Awesome picture.  I think it would look better w/o the division into three panels, but it would take more than that to screw this shot up.  Good luck.</td>', 'Awesome picture.  I think it would look better w/o the division into three panels, but it would take more than that to screw this shot up.  Good luck.', '2005-11-16 22:25:53.000000', NULL, 1),
(1875404, 256279, 14736, '<td valign="top">I enjoy each of the photos, and I understand their thematic relation, however they don''t seem to go together visually.</td>', 'I enjoy each of the photos, and I understand their thematic relation, however they don''t seem to go together visually.', '2005-11-16 22:27:37.000000', NULL, 1),
