INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1876135, 255098, 35545, '<td valign="top">This is a good picture on its own.  Why break it up?  I''d have used a darker frame.</td>', 'This is a good picture on its own.  Why break it up?  I''d have used a darker frame.', '2005-11-17 03:48:07.000000', NULL, 1),
(1876137, 255392, 32602, '<td valign="top">A found triptych! The colours need a bit of a  boost. My eye is drawn to the woman in the foreground, a few more seconds and she would have  passed the street sign and not shared her position as the subject with it.</td>', 'A found triptych! The colours need a bit of a  boost. My eye is drawn to the woman in the foreground, a few more seconds and she would have  passed the street sign and not shared her position as the subject with it.', '2005-11-17 03:48:28.000000', NULL, 1),
(1876139, 256606, 35545, '<td valign="top">It looks as if you have three good pictures here, but they are so small I can''t really tell.</td>', 'It looks as if you have three good pictures here, but they are so small I can''t really tell.', '2005-11-17 03:50:09.000000', NULL, 1),
(1876141, 257056, 32602, '<td valign="top">the black against the vibrant green is nice,  however the border breaks up the leaf  along its strong vertical line which detracts quite a bit.</td>', 'the black against the vibrant green is nice,  however the border breaks up the leaf  along its strong vertical line which detracts quite a bit.', '2005-11-17 03:51:16.000000', NULL, 1),
