INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1886398, 256424, 31885, '<td valign="top">Definitely something I would put on my wall. It actually creates an atmosphere, not just a pretty picture!</td>', 'Definitely something I would put on my wall. It actually creates an atmosphere, not just a pretty picture!', '2005-11-21 01:45:27.000000', NULL, 0),
(1886407, 255857, 31133, '<td valign="top">I loved this one - gave it a 9. All that black with the stark orange-yellow of the pear really worked for me. I can definitely imagine this hanging on my wall! Can''t believe the score you got. Hmmmmm.</td>', 'I loved this one - gave it a 9. All that black with the stark orange-yellow of the pear really worked for me. I can definitely imagine this hanging on my wall! Can''t believe the score you got. Hmmmmm.', '2005-11-21 01:49:29.000000', NULL, 0),
(1886417, 257321, 35786, '<td valign="top">it''s funny, cuz you got so many favorites out of the one with her holding the polaroids (me included!) did you even think of submitting them? They hold much more interest...</td>', 'it''s funny, cuz you got so many favorites out of the one with her holding the polaroids (me included!) did you even think of submitting them? They hold much more interest...', '2005-11-21 01:53:35.000000', NULL, 0),
